    <!-- Preloader with S and dot -->
    <div id="preloader">
      <svg viewBox="397 0 116 151" xmlns="http://www.w3.org/2000/svg">
        <!-- Outline S and dot -->
        <path class="s-outline" d="M397.08 123.39h88.43v-11.87h-88.26c-.07-1.37-.03-28.14-.21-40.51-.15-10.55 7.05-20.82 20.66-20.59 24.8.41 49.63.41 74.43-.02 10.69-.19 20.42 7.66 20.41 20.43 0 1.78-.01 3.96-.01 6.27h-88.51v11.59l88.51-.02c0 1.59.03 28.4 0 40.87-.04 12.55-8.08 20.44-20.78 20.45h-73.8c-12.8 0-20.81-7.98-20.86-20.77v-5.83"/>
        <path class="s-outline" d="M454.91 38.03c-10.46 0-18.92-8.62-18.86-19.2C436.1 8.43 444.6-.02 454.98 0c10.37.02 18.85 8.51 18.87 18.9.02 10.56-8.47 19.14-18.94 19.13"/>
        <!-- Fill S and dot (animated) -->
        <path class="s-fill" id="sFill" d="M397.08 123.39h88.43v-11.87h-88.26c-.07-1.37-.03-28.14-.21-40.51-.15-10.55 7.05-20.82 20.66-20.59 24.8.41 49.63.41 74.43-.02 10.69-.19 20.42 7.66 20.41 20.43 0 1.78-.01 3.96-.01 6.27h-88.51v11.59l88.51-.02c0 1.59.03 28.4 0 40.87-.04 12.55-8.08 20.44-20.78 20.45h-73.8c-12.8 0-20.81-7.98-20.86-20.77v-5.83"/>
        <path class="s-fill" id="dotFill" d="M454.91 38.03c-10.46 0-18.92-8.62-18.86-19.2C436.1 8.43 444.6-.02 454.98 0c10.37.02 18.85 8.51 18.87 18.9.02 10.56-8.47 19.14-18.94 19.13"/>
      </svg>
    </div>

    <div class="click-url" id="clickLayer" onclick="onAdClickTriggered()">
        <div id="adContainer" class="template_variant_class {{template_variant_class}}">
          <div id="backgroundContainer">
            <div id="imageWrapper">
              <div style="background-image:url('empty.png')" class="background_image_1" data-placeholder="{{background_image_1}}"></div>
            </div>
            <div id="videoWrapper">
              <video autoplay muted playsinline loop crossorigin="anonymous">
                <source src="" data-placeholder="{{background_video_1}}" type="video/mp4" class="background_video_1"></video>
            </div>
          </div>
          <main>
            <div id="objectWrapper">
              <div style="background-image:url('empty.png')" class="background_image_2" data-placeholder="{{background_image_2}}"></div>
            </div>
            <div id="textContainer">
              <div id="stickerContainer">
                <div class="stickerTextWrapper">
                  <p class="sticker_text_1 sticker_style_1" style="{{sticker_style_1}}">{{sticker_text_1}}</p>
                </div>
                <div class="stickerImageWrapper">
                  <div style="background-image:url('empty.png')" class="sticker_image_1" data-placeholder="{{sticker_image_1}}"></div>
                </div>
              </div>
              <div id="cardContainer">
                <div class="cardImageWrapper">
                  <div style="background-image:url('empty.png')" class="background_image_3" data-placeholder="{{background_image_3}}"></div>
                </div>
              </div>
              <div id="headlineWrapper">
                <h2 class="headline_text_1 headline_style_1" style="{{headline_style_1}}">{{headline_text_1}}</h2>
              </div>
              <div id="copyWrapper1">
                <p class="copy_text_1 copy_style_1" style="{{copy_style_1}}">{{copy_text_1}}</p>
              </div>
              <div id="copyWrapper2">
                <p class="thm copy_text_2 copy_style_2" style="{{copy_style_2}}">{{copy_text_2}}</p>
              </div>
              <div id="buttonWrapper">
                <span class="cta_text_1 cta_style_1" style="{{cta_style_1}}">{{cta_text_1}}</span>
              </div>
              <div id="disclaimerWrapper1">
