/* videoGfx positioning */ 
/*---- rightShift */
/*---- centerShift (default)*/
/*---- leftShift */




.rightShift {
    #videoWrapper > video {
        object-position: 63% 50%;
    }
}

.leftShift {
    #videoWrapper > video {
        object-position: 37% 50%;
    }
}





/* objectGfx scaling */ 
/*---- smallGfx */
/*---- mediumGfx (default)*/
/*---- largeGfx */

.smallGfx {
    #objectWrapper {
        >div {
            background-size: 75%;
            background-position: center center;
        }
    }
}

.largeGfx {
    #objectWrapper {
        width: 65%;
        height: 70%;
        left: 35%;
        bottom: 0%;
        top: auto;
    }
}

