p {
  padding: 0.1rem 0px 0px 0px;
  margin: 0px;
}
h2 {
  /*font-size:1.3rem;*/
}

h1:empty,
h2:empty,
p:empty,
.noCta #buttonWrapper span,
#buttonContainer span:empty {
  display: none;
}


/* ---------------------*/
/* gfx rules            */
/* ---------------------*/

#videoWrapper {
  display: none;
}

#objectWrapper {
  display: none;
}

.videoGfx #imageWrapper {
  display: none;
}

.videoGfx #videoWrapper {
  display: block;
}

.objectGfx #imageWrapper {
  display: none;
}

.objectGfx.fullSurfaceColor #objectWrapper {
  display: block;
}

#objectWrapper {
    position: absolute;
    width: 50%;
    height: 60%;
    left: 50%;
    bottom: 5%;
    top: auto;

    >div {
        background-size: contain;
        background-position: center bottom;
        background-repeat: no-repeat;
        width: 100%;
        height: 100%;
    }
}
