/* imageAndColor is the default layout no extra rules for that */

.imageAndColor2 #backgroundContainer { width:100%; height:50%; left:0px; }
.imageAndColor2 main {
  width: 100%;
  height: 50%;
  top:50%;
  display: flex;
}
.imageAndColor2 #textContainer  { padding-top: 0rem; width:100%;}
.imageAndColor2 #headlineWrapper  { padding-top: 0; width:70%;}
.imageAndColor2 #disclaimerWrapper1  { display: none; }
.imageAndColor2 #stickerContainer  {
  transform-origin: 100% 0%;
  right: 2rem;
  top: -2.5rem;
