/* ---------------------*/
/* color Schemes        */
/* ---------------------*/
/* blue */
/* pink or peach */
/* purple or aubergine */
/* teal or turqoise or turrkiz */
/* green or apple */
/* stone */
/* orange */
/* blue is the default --------- */

main,
.fullSurfaceColor main,
.blue main, 
.blue.fullSurfaceColor main { background: rgb(var(--blue)); }
#stickerContainer > div,
.blue #stickerContainer > div { background-color: rgb(var(--pink)); }

.purple main, 
.aubergine main,
.purple.fullSurfaceColor main, 
.aubergine.fullSurfaceColor main { background: rgb(var(--aubergine)); }
.purple #stickerContainer > div,
.aubergine #stickerContainer > div  { background-color: rgb(var(--teal)); }


.teal main, 
.turkiz main, 
.turqoise main, 
.teal.fullSurfaceColor main, 
.turkiz.fullSurfaceColor main,
.turqoise.fullSurfaceColor main { background: rgb(var(--teal)); }
.teal #stickerContainer > div,
.turkiz #stickerContainer > div,
.turqoise #stickerContainer > div  { background-color: rgb(var(--aubergine)); }


.green main, 
.apple main,
.green.fullSurfaceColor main,
.apple.fullSurfaceColor main { background: rgb(var(--apple)); }
.green #stickerContainer > div,
.apple #stickerContainer > div  { background-color: rgb(var(--aubergine)); }

.pink main, 
.peach main,
.peach.fullSurfaceColor main,
.peach.fullSurfaceColor main { background: rgb(var(--pink)); }
.pink #stickerContainer > div,
.peach #stickerContainer > div  { background-color: rgb(var(--aubergine)); }

.forest main,
.forest.fullSurfaceColor main { background: rgb(var(--forest)); }
.forest #stickerContainer > div  { background-color: rgb(var(--aubergine)); }


.stone main,
.stone.fullSurfaceColor main { background: rgb(var(--stone)); }
.stone #stickerContainer > div  { background-color: rgb(var(--pink)); }

.orange main,
.orange.fullSurfaceColor main { background: rgb(var(--orange)); }
.orange #stickerContainer > div  { background-color: rgb(var(--teal)); }


#buttonWrapper span { background-color: rgb(var(--orange)); border: 2px solid rgb(var(--orange)); }
#buttonWrapper span:hover { background-color: rgb(var(--darkOrange)); border: 2px solid rgb(var(--darkOrange));}
.orange #buttonWrapper span,
.peach #buttonWrapper span,
.pink #buttonWrapper span { background-color: rgb(var(--blue)); border: 2px solid rgb(var(--blue)); }
.orange #buttonWrapper span:hover,
.peach #buttonWrapper span:hover,
.pink #buttonWrapper span:hover { background-color: rgb(var(--darkBlue)); border: 2px solid rgb(var(--darkBlue)); }

.outlineCta #buttonWrapper span { border: 2px solid rgba(255,255,255,0.8); background-color: transparent;}
.orange.outlineCta #buttonWrapper span,
.peach.outlineCta #buttonWrapper span,
.pink.outlineCta #buttonWrapper span { background-color: rgb(var(--blue)); border: 2px solid rgb(var(--blue)); }






/* -----------------------------------------*/
/* animation                                */
/* -----------------------------------------*/

main,
.animated #backgroundContainer,
.animated #logoContainer,
.animated #frameContainer,
.animated #imageWrapper,
.animated #imageWrapper,
.animated #videoWrapper,
.animated #objecWrapper,
.animated #textContainer,
.animated #logoContainer,
.animated #stickerContainer > div {
  transition: none; /* reset layout transitions of non animated variant */
}

.animated #backgroundContainer {
  width: 100%;
  left: 0px;
  animation-name: background-animate-in;
  animation-fill-mode: forwards;
}
@keyframes background-animate-in {
  0% { width: 100%; left: 0px; }
  100% { width: 50%; left: 50%; }
}

#adContainer.animated.imageAndColor2 #backgroundContainer {
  width: 100%;
  height: 100%;
  animation-name: background-animate-in-2;
  animation-fill-mode: forwards;
}
@keyframes background-animate-in-2 {
  0% { height: 100%; }
  100% { height: 50%; }
}

@keyframes background-animate-in-3 /*for 640x360*/ {
  0% { width: 100%; left: 0px; }
  100% { width: 50%; left: 0px; }
}

@keyframes background-animate-in-4 /*for 970x250*/ {
  0% { width: 100%; left: 0px; }
  100% { width: 45%; left: 0px; }
}

#adContainer.fullSurfaceImage.animated #backgroundContainer {
  width: 100%;
  left: 0px;
  animation-name: none;
}

.animated main {
  left: -50%;
  animation-name: color-box-animate-in;
  animation-fill-mode: forwards;
}
@keyframes color-box-animate-in {
  0% { left: -50%; }
  100% { left: 0; }
}

.animated.imageAndColor2 main {
  left:0;
  top: 100%;
  animation-name: color-box-animate-in-2;
  animation-fill-mode: forwards;
}
@keyframes color-box-animate-in-2 {
  0% { top: 100%; }
  100% { top: 50%; }
}

@keyframes color-box-animate-in-3 /*for 640x360*/ {
  0% { left: 100%; }
  100% { left: 50%; }
}

@keyframes color-box-animate-in-4 /*for 970x250*/ {
  0% { left: 100%; }
  100% { left: 45%; }
}


.animated #logoContainer {
  opacity: 0;
  animation-name: opacity-animate-in;
  animation-duration: 1s;
  animation-fill-mode: forwards;
}
@keyframes opacity-animate-in {
  0% { opacity: 0; }
  100% { opacity: 1; }
}

.animated #headlineWrapper,
.animated #copyWrapper1,
.animated #copyWrapper2,
.animated #disclaimerWrapper1,
.animated #buttonWrapper {
  opacity: 0;
  position: relative;
  top: 1rem;
  animation-name: opacityandvertical-animate-in;
  animation-duration: 1s;
  animation-fill-mode: forwards;
}

@keyframes opacityandvertical-animate-in {
  0% { top: 1rem; opacity: 0; }
  100% { top: 0rem; opacity: 1; }
}

.animated.topRoundedFrame #frameContainer {
  clip-path: circle(0% at 0 0);
  animation-name: topFrame-animate-in;
  animation-timing: linear;
  animation-duration: 5s;
  animation-iteration-count: 1;
  animation-fill-mode: forwards;
}
@keyframes topFrame-animate-in {
  0% { clip-path: circle(0% at 0 0); }
  100% { clip-path: circle(150% at 100% 0); }
}

.animated.bottomRoundedFrame #frameContainer {
  clip-path: circle(0% at 0 100%);
  animation-name: bottomFrame-animate-in;
  animation-timing: linear;
  animation-duration: 5s;
  animation-iteration-count: 1;
  animation-fill-mode: forwards;
}
@keyframes bottomFrame-animate-in {
  0% { clip-path: circle(0% at 0 100%); }
  100% { clip-path: circle(150% at 100% 100%); }
}


.animated #stickerContainer > div {
  transform: scale(0.001);
  animation-name: sticker-animate-in;
  animation-duration: 10s;
  animation-iteration-count: 3.5;
  animation-fill-mode: forwards;
}
@keyframes sticker-animate-in {
  0% { transform: scale(0.001) rotate(-50deg); }
  2% { transform: scale(1.2) rotate(20deg); }
  5% { transform: scale(1) rotate(10deg); }
  95% { transform: scale(1) rotate(10deg); }
  100% { transform: scale(0.001) rotate(150deg); }
}


.animated #backgroundContainer {  animation-duration: 3s; animation-delay: 0.5s;}
.animated main { animation-duration: 2.8s; animation-delay: 0.5s;}
.animated #logoContainer { animation-delay: 2.5s; }
.animated #headlineWrapper { animation-delay: 3s; }
.animated #copyWrapper1 { animation-delay: 3.5s; }
.animated #copyWrapper2 { animation-delay: 4s; }
.animated #buttonWrapper { animation-delay: 4.5s; }
.animated #disclaimerWrapper1 { animation-delay: 4.5s; }
.animated #stickerContainer > div { animation-delay: 5s; }


.animated.fullSurfaceColor #backgroundContainer {  animation-duration: 0s; animation-delay: 0.0s;}
.animated.fullSurfaceColor main { animation-duration: 0s; animation-delay: 0.0s;}
.animated.fullSurfaceColor #logoContainer { animation-delay: 0.3s; }
.animated.fullSurfaceColor #headlineWrapper { animation-delay: 0.6s; }
.animated.fullSurfaceColor #copyWrapper1 { animation-delay: 1.2s; }
.animated.fullSurfaceColor #copyWrapper2 { animation-delay: 1.5s; }
.animated.fullSurfaceColor #buttonWrapper { animation-delay: 1.8s; }
.animated.fullSurfaceColor #disclaimerWrapper1 { animation-delay: 2.1s; }
.animated.fullSurfaceColor #stickerContainer > div { animation-delay: 2.4s; }

.animated.fullSurfaceImage #backgroundContainer {  animation-duration: 0s; animation-delay: 0.0s;}
.animated.fullSurfaceImage main { animation-duration: 0s; animation-delay: 0.0s;}
.animated.fullSurfaceImage #logoContainer { animation-delay: 0.3s; }
.animated.fullSurfaceImage #headlineWrapper { animation-delay: 0.6s; }
.animated.fullSurfaceImage #copyWrapper1 { animation-delay: 1.2s; }
.animated.fullSurfaceImage #copyWrapper2 { animation-delay: 1.5s; }
.animated.fullSurfaceImage #buttonWrapper { animation-delay: 1.8s; }
.animated.fullSurfaceImage #disclaimerWrapper1 { animation-delay: 2.1s; }
.animated.fullSurfaceImage #stickerContainer > div { animation-delay: 2.4s; }



