    <script>
    (function() {
    try {
    console.log('📢 Template script starting...');

    // ============================================================
    // PHASE 1: INITIAL SETUP
    // ============================================================

    // Check if Adform is available (may not load in sandboxed iframes)
    var isAdformContext = false;
    try {
      isAdformContext = typeof Adform !== 'undefined' &&
                        Adform !== null &&
                        typeof Adform.DynAdsHelper !== 'undefined';
    } catch(e) {
      console.log('AdForm not available (likely sandboxed iframe):', e.message);
      isAdformContext = false;
    }

    console.log('Template init - isAdformContext:', isAdformContext);

    // Preloader state - will be started after content replacement
    var preloaderStarted = false;
    var savedClasses = [];
    var hasAnimatedClass = false;
    var adContainer = document.getElementById('adContainer');

    // Save template variant classes immediately (before any modifications)
    if (adContainer) {
      var classList = Array.prototype.slice.call(adContainer.classList);
      classList.forEach(function(cls) {
        if (cls !== 'template_variant_class') {
          // Check for "animated" class - will be added back after preloader
          if (cls === 'animated') {
            hasAnimatedClass = true;
            console.log('Found "animated" class - will apply after preloader completes');
          } else {
            savedClasses.push(cls);
          }
        }
      });
      // Remove classes until preload complete (prevents animations from starting)
      adContainer.className = 'template_variant_class';
      console.log('Saved classes:', savedClasses.join(', '), hasAnimatedClass ? '(+ animated deferred)' : '');
    }

    // Set body size class
    if (adContainer) {
      document.body.classList.add('size-' + adContainer.offsetWidth + 'x' + adContainer.offsetHeight);
    }

    // ============================================================
    // PHASE 2: ADFORM INTEGRATION / INITIALIZATION
    // ============================================================
    function initAd() {
      console.log('initAd: isAdformContext =', isAdformContext);

      if (isAdformContext) {
        // AdForm context - wait for dynamic variables
        Adform.DynAdsHelper.getVars(function(variables) {
          console.log('AdForm variables received:', variables);
          onAdInitialized(variables);
        });
      } else {
        // Local preview context - directly apply data attributes to elements
        console.log('Local preview mode - applying data attributes directly');
        // Small delay to ensure DOM is ready
        setTimeout(function() {
          applyDataAttributes();
          var localValues = getLocalValues();
          onAdInitialized(localValues);
        }, 50);
      }
    }

    // Apply data-placeholder attributes directly to elements (for local preview)
    function applyDataAttributes() {
      console.log('🔄 applyDataAttributes() called');

      // Apply data-placeholder to images (background-image and img src)
      var srcElements = document.querySelectorAll('[data-placeholder]');
      console.log('Found', srcElements.length, 'elements with data-placeholder');

      for (var i = 0; i < srcElements.length; i++) {
        var el = srcElements[i];
        var dataSrc = el.getAttribute('data-placeholder');
        var className = el.className || el.tagName;

        console.log('Element', i, ':', className, '-> data-placeholder =', dataSrc ? dataSrc.substring(0, 60) : 'null');

        // Skip if still a placeholder or empty
        if (!dataSrc || dataSrc.indexOf('{{') !== -1) {
          console.log('  SKIPPED (placeholder or empty)');
          continue;
        }

        if (el.tagName === 'IMG') {
          console.log('  Before: img.src =', el.src);
          el.src = dataSrc;
          console.log('  After: img.src =', el.src);
        } else if (el.tagName === 'SOURCE') {
          el.src = dataSrc;
          if (el.parentElement && el.parentElement.tagName === 'VIDEO') {
            el.parentElement.load();
          }
          console.log('  Applied video src');
        } else {
          // Background image div
          console.log('  Before: style.backgroundImage =', el.style.backgroundImage);
          el.style.backgroundImage = 'url(' + dataSrc + ')';
          console.log('  After: style.backgroundImage =', el.style.backgroundImage);
        }
      }
      console.log('✅ applyDataAttributes() complete');
    }

    // Get values from meta tags and data attributes (local preview mode)
    function getLocalValues() {
      var values = {};

      // Known field class names
      var knownImageFields = ['background_image_1', 'background_image_2', 'background_image_3', 'background_image_4', 'sticker_image_1', 'brand_image_1', 'background_video_1'];

      // Helper to find known field name in class list
      function findKnownField(classList, knownFields) {
        for (var i = 0; i < knownFields.length; i++) {
          if (classList.indexOf(knownFields[i]) !== -1) {
            return knownFields[i];
          }
        }
        return null;
      }

      // Get from meta tags
      var metas = document.querySelectorAll('meta[name]');
      for (var i = 0; i < metas.length; i++) {
        var meta = metas[i];
        values[meta.name] = meta.content;
      }

      // Get from data-placeholder attributes (images)
      var srcElements = document.querySelectorAll('[data-placeholder]');
      for (var i = 0; i < srcElements.length; i++) {
        var el = srcElements[i];
        var classList = el.className || '';
        var fieldName = findKnownField(classList, knownImageFields);
        var dataSrc = el.getAttribute('data-placeholder');
        if (fieldName && dataSrc && dataSrc.indexOf('{{') === -1) {
          values[fieldName] = dataSrc;
        }
      }

      console.log('Local values:', values);
      return values;
    }

    // ============================================================
    // PHASE 3: AD INITIALIZED (after variables arrive)
    // ============================================================
    function onAdInitialized(variables) {
      console.log('onAdInitialized called, isAdformContext:', isAdformContext);

      // 1. Replace content placeholders with actual values (only needed in AdForm context)
      // In local preview, React has already populated the content, and applyDataAttributes() handles images
      if (isAdformContext) {
        replaceContent(variables);
      }

      // 2. Set up click tracking
      setupClickHandler(variables);

      // 3. Update body data attribute
      var advertName = variables.advert_name || document.body.getAttribute('data-advert-name') || '';
      // Clean up any remaining placeholder markers
      if (advertName.indexOf('{{') !== -1) {
        advertName = '';
      }
      document.body.setAttribute('data-advert-name', advertName);
      console.log('Advert name:', advertName);

      // 4. Check for SZK or HK and update THM if needed
      if (shouldUpdateThm(advertName)) {
        console.log('THM trigger detected in advert name - updating THM');
        updateThmFromInterests(advertName);
      } else {
        console.log('No SZK/HK in advert name - skipping THM update');
      }

      // 5. Handle directpixel if provided (AdForm tracking)
      if (isAdformContext && variables && typeof variables.directpixel !== 'undefined') {
        var dp = document.createElement('img');
        dp.setAttribute('src', variables.directpixel);
        dp.style.display = 'none';
        document.body.appendChild(dp);
        console.log('Directpixel inserted:', variables.directpixel);
      }

      // 6. Handle sticker mode for local preview (CSS visibility control)

      // 7. Start preloader image tracking (now that real URLs are in place)
      startPreloaderTracking();
    }



    // ============================================================
    // PHASE 4: CONTENT REPLACEMENT
    // ============================================================
    function replaceContent(variables) {
      console.log('replaceContent called');

      // Image mappings: variable name -> CSS selector
      var imageMappings = {
        'background_image_1': '.background_image_1',
        'background_image_2': '.background_image_2',
        'background_image_3': '.background_image_3',
        'background_image_4': '.background_image_4',
        'sticker_image_1': '.sticker_image_1',
        'brand_image_1': '.brand_image_1'
      };

      // Video mappings
      var videoMappings = {
        'background_video_1': '.background_video_1'
      };

      // Text mappings
      var textMappings = {
        'headline_text_1': '.headline_text_1',
        'copy_text_1': '.copy_text_1',
        'copy_text_2': '.copy_text_2',
        'cta_text_1': '.cta_text_1',
        'sticker_text_1': '.sticker_text_1',
        'disclaimer_text_1': '.disclaimer_text_1'
      };

      // Replace images (background-image style)
      for (var key in imageMappings) {
        var value = variables[key];
        if (value && value.indexOf('{{') === -1 && value !== 'empty.png') {
          var el = document.querySelector(imageMappings[key]);
          if (el) {
            if (el.tagName === 'IMG') {
              el.src = value;
            } else {
              el.style.backgroundImage = 'url(' + value + ')';
            }
            console.log('Replaced image:', key, '->', value.substring(0, 50) + '...');
          }
        }
      }

      // Replace videos
      for (var key in videoMappings) {
        var value = variables[key];
        if (value && value.indexOf('{{') === -1 && value !== 'emptyvideo.mp4') {
          var el = document.querySelector(videoMappings[key]);
          if (el) {
            el.src = value;
            if (el.parentElement && el.parentElement.tagName === 'VIDEO') {
              el.parentElement.load();
            }
            console.log('Replaced video:', key, '->', value.substring(0, 50) + '...');
          }
        }
      }

      // Replace text
      for (var key in textMappings) {
        var value = variables[key];
        if (value && value.indexOf('{{') === -1) {
          var el = document.querySelector(textMappings[key]);
          if (el) {
            el.innerHTML = value;
            console.log('Replaced text:', key, '->', value.substring(0, 30) + '...');
          }
        }
      }

    }

    // ============================================================
    // PHASE 5: THM LOGIC (date-dependent content)
    // ============================================================

    // Check if advert name contains SZK or HK and return the THM key to use
    function getThmKey(advertName) {
      if (!advertName) return null;
      if (advertName.indexOf('SZK') !== -1) return 'SZK_THM';
      if (advertName.indexOf('HK') !== -1) return 'HK_THM';
      return null;
    }

    function shouldUpdateThm(advertName) {
      return getThmKey(advertName) !== null;
    }

    function updateThmFromInterests(advertName) {
      try {
        if (!document.interests) {
          console.error('THM: document.interests not found');
          return;
        }

        var thmKey = getThmKey(advertName);
        if (!thmKey) {
          console.error('THM: No THM key found for advert name:', advertName);
          return;
        }

        var thmData = document.interests[thmKey];
        if (!thmData) {
          console.error('THM: No data found for key:', thmKey);
          return;
        }

        console.log('THM using key:', thmKey, 'data:', thmData);
        var thmElement = document.querySelector('.thm');

        if (!thmElement) {
          console.error('THM: .thm element not found');
          return;
        }

        var now = new Date();
        // For testing: now.setDate(now.getDate() + 1);

        var intervals = Object.keys(thmData);
        for (var i = 0; i < intervals.length; i++) {
          var interval = intervals[i];
          var intervalDates = interval.split('_');

          var startDate = Date.parse(intervalDates[0]);
          var endDate = Date.parse(intervalDates[1]);

          var startDateLaterThanNow = now > startDate;
          var endDateEarlierThanNow = now <= endDate;

          if (startDateLaterThanNow && endDateEarlierThanNow) {
            var newValue = thmData[interval];
            thmElement.innerHTML = newValue;
            console.log('THM updated to:', newValue, '(from', thmKey + ')');
            return;
          }
        }

        if (!thmElement.innerHTML || !thmElement.innerHTML.trim().length) {
          console.error('THM: No matching interval found for', thmKey);
        }
      } catch(error) {
        console.error('THM error:', error);
      }
    }

    // ============================================================
    // PHASE 6: CLICK HANDLER
    // ============================================================
    function setupClickHandler(variables) {
      if (isAdformContext && typeof dhtml !== 'undefined') {
        window.clickTAGvalue = dhtml.getVar('clickTAG', variables.click_url || '');
        window.landingpagetarget = dhtml.getVar('landingPageTarget', '_blank');
      } else {
        // Local preview mode
        var metaClickUrl = document.querySelector('meta[name="click_url"]');
        window.clickTAGvalue = variables.click_url || (metaClickUrl ? metaClickUrl.content : '') || '#';
        window.landingpagetarget = '_blank';
      }
      console.log('Click URL set:', window.clickTAGvalue);
    }

    window.onAdClickTriggered = function() {
      console.log('Click triggered:', window.clickTAGvalue);
      if (window.clickTAGvalue && window.clickTAGvalue !== '#') {
        window.open(window.clickTAGvalue, window.landingpagetarget);
      }
    };

    // ============================================================
    // PHASE 7: PRELOADER (starts AFTER content replacement)
    // ============================================================
    function startPreloaderTracking() {
      if (preloaderStarted) return;
      preloaderStarted = true;

      console.log('Starting preloader tracking...');

      var preloader = document.getElementById('preloader');
      var sFill = document.getElementById('sFill');
      var dotFill = document.getElementById('dotFill');
      var startTime = Date.now();

      function setStatus(text) {
        var elapsed = ((Date.now() - startTime) / 1000).toFixed(1);
        console.log('Preloader [' + elapsed + 's]:', text);
      }

      // Function to restore classes and trigger animations
      function triggerAnimations() {
        if (adContainer) {
          // Restore saved classes
          if (savedClasses.length > 0) {
            adContainer.className = savedClasses.join(' ');
          }
          // Add "animated" class after preloader to start CSS animations
          if (hasAnimatedClass) {
            // Small delay to ensure layout is stable before animations start
            setTimeout(function() {
              adContainer.classList.add('animated');
              console.log('Added "animated" class - CSS animations starting');
            }, 50);
          }
          console.log('Restored classes:', adContainer.className);
        }
      }

      // Get all images to track (now with real URLs)
      var images = Array.prototype.slice.call(document.querySelectorAll('img'));
      var bgElements = Array.prototype.slice.call(document.querySelectorAll('[style*="background-image"]'));

      setStatus('Found: ' + images.length + ' img, ' + bgElements.length + ' bg');

      // Extract background image URLs (skip empty.png and placeholders)
      // Use el.style.backgroundImage which contains the updated URL after applyDataAttributes()
      var bgUrls = bgElements
        .map(function(el) {
          var bgImage = el.style.backgroundImage || '';
          var match = bgImage.match(/url\(['"]?([^'")\s]+)['"]?\)/);
          return match ? match[1] : null;
        })
        .filter(function(url) {
          return url && url.indexOf('{{') === -1 && url !== 'empty.png';
        });

      setStatus('BG URLs to load: ' + bgUrls.length);

      // Filter img elements (skip empty, data URIs, and empty.png)
      images = images.filter(function(img) {
        return img.src &&
               img.src.indexOf('empty.png') === -1 &&
               img.src.indexOf('data:') !== 0 &&
               img.src.length > 0;
      });

      // Create image objects for background images
      var bgImages = bgUrls.map(function(url) {
        var img = new Image();
        img.src = url;
        return img;
      });

      var allImages = images.concat(bgImages);
      var totalItems = allImages.length;
      var loadedItems = 0;

      setStatus('Total items to track: ' + totalItems + ' images');

      function updateProgress(source) {
        loadedItems++;
        var progress = totalItems > 0 ? (loadedItems / totalItems) : 1;
        var fillPercent = 100 - (progress * 100);

        setStatus('Loaded ' + loadedItems + '/' + totalItems + ' (' + source + ')');

        // Animate fill from bottom to top
        var clipPath = 'inset(' + fillPercent + '% 0 0 0)';
        if (sFill) sFill.style.clipPath = clipPath;
        if (dotFill) dotFill.style.clipPath = clipPath;

        // Hide preloader when all loaded
        if (loadedItems >= totalItems) {
          hidePreloader();
        }
      }

      function hidePreloader() {
        setStatus('All loaded! Hiding...');
        setTimeout(function() {
          if (preloader) preloader.classList.add('hidden');
          triggerAnimations();
          setTimeout(function() {
            if (preloader) preloader.remove();
          }, 400);
        }, 200);
      }

      // Track image loading
      allImages.forEach(function(img, i) {
        var src = img.src ? img.src.split('/').pop() : 'img' + i;
        if (img.complete) {
          updateProgress('img done: ' + src);
        } else {
          img.addEventListener('load', function() {
            updateProgress('img load: ' + src);
          });
          img.addEventListener('error', function() {
            console.error('Image load failed:', img.src);
            updateProgress('img err: ' + src);
          });
        }
      });

      // Fallback: hide preloader after max 3 seconds (reduced for better UX)
      setTimeout(function() {
        if (preloader && !preloader.classList.contains('hidden')) {
          setStatus('TIMEOUT! Only ' + loadedItems + '/' + totalItems + ' loaded');
          if (sFill) sFill.style.clipPath = 'inset(0 0 0 0)';
          if (dotFill) dotFill.style.clipPath = 'inset(0 0 0 0)';
          hidePreloader();
        }
      }, 3000);

      // If no items to load, hide immediately
      if (totalItems === 0) {
        setStatus('No items to load');
        if (sFill) sFill.style.clipPath = 'inset(0 0 0 0)';
        if (dotFill) dotFill.style.clipPath = 'inset(0 0 0 0)';
        setTimeout(hidePreloader, 300);
      }
    }

    // ============================================================
    // INIT - Start the ad initialization
    // ============================================================
    // Wait for DOM to be ready
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', initAd);
    } else {
      // DOM already loaded
      initAd();
    }

    } catch(globalError) {
      console.error('❌ Template script error:', globalError);
    }
    })();
